import{_ as e,o as a,c as r,a2 as i}from"./chunks/framework.il0noOp3.js";const m=JSON.parse('{"title":"Sustainability Manager Well-Architected — enumerated source for the Microsoft Sustainability Manager Well-Architected assessment","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/sustainability-manager-well-architected-question-set.md","filePath":"frameworks/sustainability-manager-well-architected-question-set.md"}'),d={name:"frameworks/sustainability-manager-well-architected-question-set.md"};function n(s,t,o,c,l,h){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="sustainability-manager-well-architected-—-enumerated-source-for-the-microsoft-sustainability-manager-well-architected-assessment" tabindex="-1">Sustainability Manager Well-Architected — enumerated source for the Microsoft Sustainability Manager Well-Architected assessment <a class="header-anchor" href="#sustainability-manager-well-architected-—-enumerated-source-for-the-microsoft-sustainability-manager-well-architected-assessment" aria-label="Permalink to &quot;Sustainability Manager Well-Architected — enumerated source for the Microsoft Sustainability Manager Well-Architected assessment&quot;">​</a></h1><p><strong>Enumerated 2026-11-25. Verification method and limits are stated below — read them before quoting any coverage number from this page.</strong></p><p>Scout&#39;s <code>msm.wellarchitected.yaml</code> reviews an implementation of Microsoft&#39;s sustainability application against the Well-Architected for Industry guidance. It is Scout&#39;s counterpart to the <a href="https://learn.microsoft.com/en-us/assessments/333d9326-e34c-40e1-88d9-8342afceec36/" target="_blank" rel="noreferrer">Microsoft Sustainability Manager | Well-Architected Assessment</a>, which Microsoft Learn now lists as the Microsoft Dynamics 365 Sustainability Assessment. <code>src/assess/rules/msm.wellarchitected.yaml</code> is written against this page only, and every rule cites an item number from the tables below. Every item is a <strong>manual</strong> question answered with <code>-AssessmentAnswers</code>, because Scout does not read Dataverse or Power Platform data.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Assessment</td><td>[Microsoft Sustainability Manager</td></tr><tr><td>Framework version</td><td>Well-Architected for Dynamics 365 Sustainability and Well-Architected for Industry on Microsoft Learn, current as of the extraction date; no published version number</td></tr><tr><td>Extraction date</td><td>2026-11-25</td></tr><tr><td>Verification method</td><td>Pages marked <code>fetched</code> in the source list were fetched in full with the Microsoft Learn MCP <code>microsoft_docs_fetch</code> tool on 2026-11-25. Pages marked <code>search excerpt</code> were read through <code>microsoft_docs_search</code> excerpts on the same day, not in full. The Dataverse, Power Platform and Azure interfaces named in the last section were checked against Learn reference pages the same day. No Dataverse environment was read.</td></tr></tbody></table><h2 id="product-status" tabindex="-1">Product status <a class="header-anchor" href="#product-status" aria-label="Permalink to &quot;Product status&quot;">​</a></h2><p>Checked against Microsoft Learn on 2026-11-25.</p><ul><li><strong>Renamed, not retired.</strong> Microsoft Sustainability Manager has been rebranded as <strong>Dynamics 365 Sustainability</strong>. Every page in the Well-Architected set carries the note that this is a new product name only, with functionality, capabilities, licensing and service offerings unchanged. Learn&#39;s Well-Architected for Industry overview lists this same assessment as the &quot;Microsoft Dynamics 365 Sustainability Assessment&quot;. Scout keeps the <code>MSM-</code> prefix and the assessment name from the catalog title, and says &quot;Dynamics 365 Sustainability&quot; where it cites current guidance.</li><li><strong>Umbrella name.</strong> Current reference-architecture pages say Microsoft for Sustainability where older pages (and the Learn training module) say Microsoft Cloud for Sustainability.</li><li><strong>Preview capabilities.</strong> The guidance marks some Scope 3 categories, the water and waste data models, Teams collaboration and data approval management as preview. MSM-CF-08 and MSM-DI-07 ask whether production depends on them.</li><li><strong>Replacement guidance.</strong> The Well-Architected for Dynamics 365 Sustainability pages (design principles, design and deployment and monitoring checklists, best practices) are the current source; the groups below follow them.</li></ul><h2 id="the-one-thing-this-enumeration-is-not" tabindex="-1">The one thing this enumeration is NOT <a class="header-anchor" href="#the-one-thing-this-enumeration-is-not" aria-label="Permalink to &quot;The one thing this enumeration is NOT&quot;">​</a></h2><p><strong>The questions are Scout-derived, not Microsoft&#39;s.</strong> The assessment&#39;s question text is not published, so the items below are Scout&#39;s reading of the guidance listed above. The <code>MSM-*</code> IDs, and the assignment of an item to a group, are Scout&#39;s own.</p><p><strong>Scout does not read this product&#39;s data yet.</strong> Dynamics 365 Sustainability runs on Dataverse and the Power Platform. Scout reads Azure (Resource Graph and ARM) and one Microsoft Entra policy; it does not read Dataverse settings, Power Platform environments or Microsoft Entra Conditional Access, and the collect.json contract in <code>src/collect/Invoke-Collect.ps1</code> holds none of that. So every rule is <code>manual: true</code> with <code>query: null</code>: it is exported as a question by <code>Export-ScoutAssessmentQuestion</code>, answered with <code>-AssessmentAnswers</code> (see <a href="./../assessment/questionnaire-answers.html">Questionnaire Answers</a>), and stays Manual and out of the score until answered. Azure resources that sit around the solution (Synapse, storage, gateways, Application Insights) are covered by Scout&#39;s Azure assessments, not by this one.</p><p>Sources:</p><ul><li>[WAI] <a href="https://learn.microsoft.com/industry/well-architected/overview" target="_blank" rel="noreferrer">Overview of Well-Architected for Industry (lists the Dynamics 365 Sustainability assessment)</a> -- fetched</li><li>[OV] <a href="https://learn.microsoft.com/dynamics365/sustainability/well-architected/d365-sustainability-overview" target="_blank" rel="noreferrer">Overview of Dynamics 365 Sustainability (formerly Microsoft Sustainability Manager)</a> -- fetched</li><li>[DP] <a href="https://learn.microsoft.com/dynamics365/sustainability/well-architected/cloud-sustainability-design-principles" target="_blank" rel="noreferrer">Design principles for Dynamics 365 Sustainability</a> -- fetched</li><li>[ARCHS] <a href="https://learn.microsoft.com/dynamics365/sustainability/well-architected/d365-sustainability-architecture" target="_blank" rel="noreferrer">Reference architecture for Dynamics 365 Sustainability</a> -- fetched</li><li>[DCON] <a href="https://learn.microsoft.com/dynamics365/sustainability/well-architected/design-consideration" target="_blank" rel="noreferrer">Design considerations for Dynamics 365 Sustainability</a> -- fetched</li><li>[DBP] <a href="https://learn.microsoft.com/dynamics365/sustainability/well-architected/design-bestpractice" target="_blank" rel="noreferrer">Design best practices for Dynamics 365 Sustainability</a> -- fetched</li><li>[DCL] <a href="https://learn.microsoft.com/dynamics365/sustainability/well-architected/design-checklist" target="_blank" rel="noreferrer">Design checklist for Dynamics 365 Sustainability</a> -- fetched</li><li>[DEP] <a href="https://learn.microsoft.com/dynamics365/sustainability/well-architected/deploy-consideration" target="_blank" rel="noreferrer">Deployment considerations for Dynamics 365 Sustainability</a> -- fetched</li><li>[DEPB] <a href="https://learn.microsoft.com/dynamics365/sustainability/well-architected/deploy-bestpractice" target="_blank" rel="noreferrer">Deployment best practices for Dynamics 365 Sustainability</a> -- fetched</li><li>[MON] <a href="https://learn.microsoft.com/dynamics365/sustainability/well-architected/monitor-consideration" target="_blank" rel="noreferrer">Monitoring considerations for Dynamics 365 Sustainability</a> -- fetched</li><li>[MONB] <a href="https://learn.microsoft.com/dynamics365/sustainability/well-architected/monitor-bestpractice" target="_blank" rel="noreferrer">Monitoring best practices for Dynamics 365 Sustainability</a> -- fetched</li><li>[HS] <a href="https://learn.microsoft.com/dynamics365/sustainability/well-architected/sustainability-hierarchical-security" target="_blank" rel="noreferrer">Implement hierarchical security in Dynamics 365 Sustainability</a> -- search excerpt</li><li>[REFA] <a href="https://learn.microsoft.com/dynamics365/sustainability/well-architected/sustainability-architecture-overview" target="_blank" rel="noreferrer">Overview of Microsoft for Sustainability reference architectures</a> -- search excerpt</li><li>[COMP] <a href="https://learn.microsoft.com/dynamics365/sustainability/compliance-overview" target="_blank" rel="noreferrer">Compliance in Microsoft for Sustainability</a> -- search excerpt</li><li>[CAF] <a href="https://learn.microsoft.com/azure/cloud-adoption-framework/strategy/inform/sustainability" target="_blank" rel="noreferrer">Sustainability considerations in your cloud strategy (Cloud Adoption Framework)</a> -- search excerpt</li></ul><p>Every item is <strong>manual</strong>: it is exported as a question and scored only when answered with <code>-AssessmentAnswers</code> (see <a href="./../assessment/questionnaire-answers.html">Questionnaire Answers</a>).</p><h2 id="the-enumeration-—-47-items-across-9-groups" tabindex="-1">The enumeration — 47 items across 9 groups <a class="header-anchor" href="#the-enumeration-—-47-items-across-9-groups" aria-label="Permalink to &quot;The enumeration — 47 items across 9 groups&quot;">​</a></h2><h3 id="configure-the-solution-msm-cf-—-8-items" tabindex="-1">Configure the solution (MSM-CF) — 8 items <a class="header-anchor" href="#configure-the-solution-msm-cf-—-8-items" aria-label="Permalink to &quot;Configure the solution (MSM-CF) — 8 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>MSM-CF-01</td><td>Organisation data (business units, facilities, reporting years) is configured before activity data is imported</td><td>Manual</td><td>DCL, DBP</td></tr><tr><td>MSM-CF-02</td><td>Reference data is configured before activity data, to the regulations, conversions and granularity required</td><td>Manual</td><td>DCL, DBP</td></tr><tr><td>MSM-CF-03</td><td>The first rollout covers one scenario or emission scope end to end before widening</td><td>Manual</td><td>DBP</td></tr><tr><td>MSM-CF-04</td><td>Units and unit conversions are specified and checked against the activity and model units</td><td>Manual</td><td>DCL, DBP</td></tr><tr><td>MSM-CF-05</td><td>Emission factors and factor mappings are complete, and the factor libraries are kept current</td><td>Manual</td><td>DCL, DBP, DCON</td></tr><tr><td>MSM-CF-06</td><td>Calculation models are tested on small data sets, and calculation jobs stay under the record limit</td><td>Manual</td><td>DCL, DBP</td></tr><tr><td>MSM-CF-07</td><td>The calculation methodology is decided and documented, using copies of the built-in models where changes are needed</td><td>Manual</td><td>DP, DCON</td></tr><tr><td>MSM-CF-08</td><td>Preview capabilities (some Scope 3 categories, water and waste data models, Teams collaboration) are not relied on in production</td><td>Manual</td><td>DCON</td></tr></tbody></table><h3 id="data-ingestion-and-integration-msm-di-—-8-items" tabindex="-1">Data ingestion and integration (MSM-DI) — 8 items <a class="header-anchor" href="#data-ingestion-and-integration-msm-di-—-8-items" aria-label="Permalink to &quot;Data ingestion and integration (MSM-DI) — 8 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>MSM-DI-01</td><td>A data ingestion strategy is set per source (Excel template, Power Query, partner connector, pipeline or manual)</td><td>Manual</td><td>DP, ARCHS</td></tr><tr><td>MSM-DI-02</td><td>Native Power Query connectors are preferred to custom connectors</td><td>Manual</td><td>DP, ARCHS</td></tr><tr><td>MSM-DI-03</td><td>Data connections use service accounts, not the account of the person who built them</td><td>Manual</td><td>DCL, DBP, DCON</td></tr><tr><td>MSM-DI-04</td><td>Data refresh is scheduled for every connection at the frequency the reporting needs</td><td>Manual</td><td>DBP, DCON</td></tr><tr><td>MSM-DI-05</td><td>Import hygiene is followed: latest templates, transformation checklist, validated auto-mapping</td><td>Manual</td><td>DCL, DCON</td></tr><tr><td>MSM-DI-06</td><td>Only the activity data needed for calculations is ingested</td><td>Manual</td><td>DP</td></tr><tr><td>MSM-DI-07</td><td>Import errors are reviewed and fixed, and data approval staging is used where needed (preview)</td><td>Manual</td><td>ARCHS</td></tr><tr><td>MSM-DI-08</td><td>The on-premises data gateway is clustered for availability, and its recovery keys and environments are managed</td><td>Manual</td><td>DBP, DCON</td></tr></tbody></table><h3 id="extend-the-solution-msm-ex-—-4-items" tabindex="-1">Extend the solution (MSM-EX) — 4 items <a class="header-anchor" href="#extend-the-solution-msm-ex-—-4-items" aria-label="Permalink to &quot;Extend the solution (MSM-EX) — 4 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>MSM-EX-01</td><td>Extensions include only the components they change, and default solution components are cloned, not overridden</td><td>Manual</td><td>DBP, DCON</td></tr><tr><td>MSM-EX-02</td><td>Custom dimensions are considered before the data model is extended</td><td>Manual</td><td>DBP, DCON</td></tr><tr><td>MSM-EX-03</td><td>The Power Apps solution checker is run regularly on customisations</td><td>Manual</td><td>DCL, DBP</td></tr><tr><td>MSM-EX-04</td><td>Extensions use supported techniques, are tested at volume and are deployed through ALM automation</td><td>Manual</td><td>DCL</td></tr></tbody></table><h3 id="security-identity-and-access-msm-se-—-8-items" tabindex="-1">Security, identity and access (MSM-SE) — 8 items <a class="header-anchor" href="#security-identity-and-access-msm-se-—-8-items" aria-label="Permalink to &quot;Security, identity and access (MSM-SE) — 8 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>MSM-SE-01</td><td>Least privilege: built-in roles are copied per business unit and custom roles are copied from existing roles</td><td>Manual</td><td>DP, DCL, DBP</td></tr><tr><td>MSM-SE-02</td><td>Business units, Entra groups and an environment security group segment access</td><td>Manual</td><td>DCL, DEPB, HS</td></tr><tr><td>MSM-SE-03</td><td>Administrator access to the environments is limited through a Privileged Identity Management group</td><td>Manual -- PIM eligibility is not in collect.json</td><td>DCL</td></tr><tr><td>MSM-SE-04</td><td>Conditional Access with multifactor authentication applies to users of the application</td><td>Manual -- Conditional Access policies are not in collect.json</td><td>ARCHS</td></tr><tr><td>MSM-SE-05</td><td>Defender for Cloud protects the related resources, and Sentinel is considered for signals</td><td>Manual</td><td>DCL, DBP</td></tr><tr><td>MSM-SE-06</td><td>Purview classifies the Dataverse and Power BI data used by the solution</td><td>Manual</td><td>DBP, MONB</td></tr><tr><td>MSM-SE-07</td><td>The limits of dashboard and insights access control are understood and handled</td><td>Manual</td><td>DCON, HS</td></tr><tr><td>MSM-SE-08</td><td>Exports to external analytical stores are secured and given only to people who need them</td><td>Manual</td><td>DCL</td></tr></tbody></table><h3 id="deployment-monitoring-and-operations-msm-ob-—-5-items" tabindex="-1">Deployment, monitoring and operations (MSM-OB) — 5 items <a class="header-anchor" href="#deployment-monitoring-and-operations-msm-ob-—-5-items" aria-label="Permalink to &quot;Deployment, monitoring and operations (MSM-OB) — 5 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>MSM-OB-01</td><td>Dataverse auditing is turned on in every environment</td><td>Manual</td><td>MON, MONB</td></tr><tr><td>MSM-OB-02</td><td>Dataverse diagnostics go to Application Insights and Log Analytics, with alerts for admins and owners</td><td>Manual</td><td>MONB</td></tr><tr><td>MSM-OB-03</td><td>Power Platform analytics are exported to a data lake or Application Insights and kept as long as policy requires</td><td>Manual</td><td>MON, MONB</td></tr><tr><td>MSM-OB-04</td><td>Deployments are planned: sample data is off for test and production, and time is reserved for installs</td><td>Manual</td><td>DEP</td></tr><tr><td>MSM-OB-05</td><td>Azure Synapse Link for Dataverse is deployed in the right tenant and region with change tracking enabled</td><td>Manual</td><td>DEP</td></tr></tbody></table><h3 id="privacy-compliance-and-regulatory-fit-msm-pc-—-4-items" tabindex="-1">Privacy, compliance and regulatory fit (MSM-PC) — 4 items <a class="header-anchor" href="#privacy-compliance-and-regulatory-fit-msm-pc-—-4-items" aria-label="Permalink to &quot;Privacy, compliance and regulatory fit (MSM-PC) — 4 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>MSM-PC-01</td><td>Regulatory and disclosure requirements are identified for each country where the organisation operates</td><td>Manual</td><td>DBP, REFA</td></tr><tr><td>MSM-PC-02</td><td>Product availability, countries or regions and languages match the tenant</td><td>Manual</td><td>DCON</td></tr><tr><td>MSM-PC-03</td><td>Compliance offerings and privacy terms were reviewed against the organisation requirements</td><td>Manual</td><td>DCL, COMP</td></tr><tr><td>MSM-PC-04</td><td>Data residency needs for transactional data are defined and drive the retention design</td><td>Manual</td><td>DBP</td></tr></tbody></table><h3 id="reporting-and-analytics-msm-rp-—-4-items" tabindex="-1">Reporting and analytics (MSM-RP) — 4 items <a class="header-anchor" href="#reporting-and-analytics-msm-rp-—-4-items" aria-label="Permalink to &quot;Reporting and analytics (MSM-RP) — 4 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>MSM-RP-01</td><td>Reporting years and periods match the organisation reporting requirements before data is imported</td><td>Manual</td><td>DCL</td></tr><tr><td>MSM-RP-02</td><td>The default reports and embedded intelligence are used before custom reports are built</td><td>Manual</td><td>DCL, ARCHS</td></tr><tr><td>MSM-RP-03</td><td>The data estate is mapped and an analytics strategy covers current and future reporting needs</td><td>Manual</td><td>DCL</td></tr><tr><td>MSM-RP-04</td><td>Custom reports read exported data (Synapse or Data Lake), not the managed data lake</td><td>Manual</td><td>DCON, ARCHS</td></tr></tbody></table><h3 id="reliability-cost-and-performance-msm-pi-—-4-items" tabindex="-1">Reliability, cost and performance (MSM-PI) — 4 items <a class="header-anchor" href="#reliability-cost-and-performance-msm-pi-—-4-items" aria-label="Permalink to &quot;Reliability, cost and performance (MSM-PI) — 4 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>MSM-PI-01</td><td>The Azure reliability design checklist is applied to the Azure parts of the solution</td><td>Manual</td><td>DCON</td></tr><tr><td>MSM-PI-02</td><td>The Dataverse entitlement is tracked, and extra capacity is planned and approved</td><td>Manual</td><td>DCON, DBP</td></tr><tr><td>MSM-PI-03</td><td>Historical data is archived to cheaper long-term storage within the retention policy</td><td>Manual</td><td>DCON, DBP</td></tr><tr><td>MSM-PI-04</td><td>Ingestion design respects Power Query and Dataverse service protection limits and keeps sources in one cloud and region</td><td>Manual</td><td>DCON, DBP</td></tr></tbody></table><h3 id="emissions-from-it-operations-msm-it-—-2-items" tabindex="-1">Emissions from IT operations (MSM-IT) — 2 items <a class="header-anchor" href="#emissions-from-it-operations-msm-it-—-2-items" aria-label="Permalink to &quot;Emissions from IT operations (MSM-IT) — 2 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>MSM-IT-01</td><td>Emissions from IT operations are measured with the Emissions Impact Dashboard and Azure carbon optimization</td><td>Manual</td><td>REFA, CAF</td></tr><tr><td>MSM-IT-02</td><td>Emissions from IT operations feed the organisation sustainability reporting</td><td>Manual</td><td>REFA, CAF</td></tr></tbody></table><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Group</th><th>Items</th><th>Automated</th><th>Manual</th></tr></thead><tbody><tr><td>Configure the solution</td><td>8</td><td>0</td><td>8</td></tr><tr><td>Data ingestion and integration</td><td>8</td><td>0</td><td>8</td></tr><tr><td>Extend the solution</td><td>4</td><td>0</td><td>4</td></tr><tr><td>Security, identity and access</td><td>8</td><td>0</td><td>8</td></tr><tr><td>Deployment, monitoring and operations</td><td>5</td><td>0</td><td>5</td></tr><tr><td>Privacy, compliance and regulatory fit</td><td>4</td><td>0</td><td>4</td></tr><tr><td>Reporting and analytics</td><td>4</td><td>0</td><td>4</td></tr><tr><td>Reliability, cost and performance</td><td>4</td><td>0</td><td>4</td></tr><tr><td>Emissions from IT operations</td><td>2</td><td>0</td><td>2</td></tr><tr><td><strong>Total</strong></td><td><strong>47</strong></td><td><strong>0</strong></td><td><strong>47</strong></td></tr></tbody></table><h2 id="what-an-automated-version-would-need" tabindex="-1">What an automated version would need <a class="header-anchor" href="#what-an-automated-version-would-need" aria-label="Permalink to &quot;What an automated version would need&quot;">​</a></h2><p>Everything below needs an app registration or service principal with read-only access to the environment, a new collect section, and a gate on each rule so an environment that was not read reports Not assessed instead of Pass.</p><table tabindex="0"><thead><tr><th>Items</th><th>What would be read</th><th>Interface and permission</th></tr></thead><tbody><tr><td>MSM-OB-01</td><td>Whether auditing is on and its retention</td><td>Dataverse Web API <code>GET [org URI]/api/data/v9.2/organizations?$select=isauditenabled,auditretentionperiodv2,isuseraccessauditenabled,useraccessauditinginterval</code>; any user can read the configuration, changing it needs System Administrator or System Customizer</td></tr><tr><td>MSM-OB-01</td><td>Which tables are audited</td><td>Dataverse Web API <code>GET .../EntityDefinitions?$select=LogicalName,IsAuditEnabled&amp;$filter=IsAuditEnabled/Value eq true and IsPrivate eq false</code></td></tr><tr><td>MSM-OB-02, OB-03</td><td>Data export packages to Application Insights and Data Lake</td><td>Power Platform admin center data export (needs a managed environment and a premium Dataverse licence); no read API was confirmed in this pass</td></tr><tr><td>MSM-SE-01, SE-02</td><td>Security roles, business units and teams</td><td>Dataverse Web API tables <code>role</code>, <code>businessunit</code>, <code>team</code> (not researched in this pass)</td></tr><tr><td>MSM-SE-03, SE-04</td><td>Conditional Access and PIM for the sustainability users and admins</td><td>Microsoft Graph v1.0 <code>GET /identity/conditionalAccess/policies</code>; <code>Policy.Read.All</code>. PIM eligibility is a separate Graph API not researched in this pass.</td></tr><tr><td>MSM-SE-05, OB-02</td><td>Defender for Cloud plans, Application Insights export target</td><td>Azure Resource Graph and ARM, which Scout already reads</td></tr><tr><td>MSM-IT-01, IT-02</td><td>Azure emissions</td><td>Azure carbon optimization and the Emissions Impact Dashboard (not researched in this pass)</td></tr></tbody></table><p>Items about method, data quality, reporting design and organisation (most of MSM-CF, MSM-DI, MSM-EX, MSM-PC and MSM-RP) have no API behind them and stay manual in any version.</p>',39)])])}const p=e(d,[["render",n]]);export{m as __pageData,p as default};
